/* generado por prompts/herramientas/clave-mejoras-datos.js; no editar a mano */
(window.CLAVE_ARTF=window.CLAVE_ARTF||{})[15]=[["<mark class=\"m-plazo\">Artículo</mark> 1. Objeto de la Ley <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R1</span>","<p data-ex=\"*\"><b>1.</b> La presente Ley tiene por <span class=\"ex-plg\"><span class=\"ex-plg-t\">objeto actuar contra la violencia que, como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres, se ejerce</span></span> sobre éstas por parte de <mark class=\"m-resp\" data-q=\"15-5\">quienes sean o hayan sido sus cónyuges</mark> o <span class=\"ex-plg\"><span class=\"ex-plg-t\">de quienes estén o hayan estado ligados a ellas</span></span> por relaciones similares de afectividad, <mark class=\"m-resp r-ia\" data-q=\"15-ia-1001\">aun sin convivencia</mark>.</p><p data-ex=\"EX\"><b>2.</b> Por esta ley se establecen <span class=\"ex-plg\"><span class=\"ex-plg-t\">medidas de protección integral cuya</span></span> finalidad es prevenir, sancionar y <mark class=\"m-resp\" data-q=\"15-245\">erradicar</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">esta violencia y prestar asistencia a las mujeres, a sus hijos <mark class=\"m-autoridad\">menores</mark> y a los <mark class=\"m-autoridad\">menores</mark> sujetos a su tutela, o guarda y custodia, víctimas de esta violencia.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1002\">🎯 1 pregunta</mark></p><p data-ex=\"EX\" data-r=\"R1\"><span class=\"ex-sello ex-sello-r\">R1</span> <b>3.</b> La violencia de género a que se refiere la presente Ley comprende <mark class=\"m-resp\" data-q=\"15-141,15-282\">todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad</mark>.</p><p><b>4.</b> La violencia de género a <span class=\"ex-plg\"><span class=\"ex-plg-t\">que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados <mark class=\"m-autoridad\">menores</mark> de edad por parte de las <mark class=\"m-autoridad\">personas</mark> indicadas en el apartado primero.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1004\">🎯 1 pregunta</mark></p>"],["<mark class=\"m-autoridad\">Artículo</mark> 2. Principios rectores <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p style=\"margin-left:18px\" data-ex=\"*\"><b>a)</b> Fortalecer las medidas de sensibilización <span class=\"ex-plg\"><span class=\"ex-plg-t\">ciudadana de prevención, dotando a los poderes públicos de instrumentos eficaces en el ámbito <mark class=\"m-destacable\">educativo, servicios sociales, sanitario, publicitario</mark> y <mark class=\"m-destacable\">mediático.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-21,15-ia-1005\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\" data-ex=\"EXOF\"><b><mark class=\"m-autoridad\">c)</mark></b> <mark class=\"m-personalizado\">Reforzar hasta la consecución de los mínimos exigidos por los objetivos de la ley los servicios</mark> sociales de información, de <span class=\"ex-plg\"><span class=\"ex-plg-t\">atención, de emergencia, de apoyo y de recuperación integral, así como establecer un sistema para la más eficaz coordinación de los</span></span> servicios ya existentes a nivel <mark class=\"m-resp r-ia\" data-q=\"15-ia-1006\">municipal y autonómico</mark>.</p><p style=\"margin-left:18px\"><b>f)</b> Establecer un sistema integral de <span class=\"ex-plg\"><span class=\"ex-plg-t\">tutela institucional en el que la Administración General del</span></span> <mark class=\"m-autoridad\">Estado,</mark> a través de la <mark class=\"m-resp r-ia\" data-q=\"15-ia-1007\">Delegación Especial del <mark class=\"m-autoridad\">Gobierno</mark> contra la Violencia sobre la Mujer</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">en colaboración con el Observatorio Estatal de la Violencia sobre la Mujer, impulse la creación de políticas públicas dirigidas a ofrecer tutela a las víctimas de la violencia contemplada en la presente Ley.</span></span></p><p style=\"margin-left:18px\" data-ex=\"*\"><b><mark class=\"m-autoridad\">g)</mark></b> Fortalecer el marco penal y <span class=\"ex-plg\"><span class=\"ex-plg-t\">procesal vigente para asegurar</span></span> una protección integral, desde las <mark class=\"m-resp\" data-q=\"15-286\">instancias jurisdiccionales, a las víctimas de violencia de género</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1008\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>k)</b> Garantizar el principio de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1009\">transversalidad</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">las medidas, de manera que en su aplicación se tengan en cuenta las <mark class=\"m-personalizado\">necesidades y demandas específicas</mark> de <mark class=\"m-autoridad\">todas las mujeres</mark> víctimas de violencia de género.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-190,15-40\">🎯 2 preguntas</mark></p>"],["Artículo 3. <mark class=\"m-destacable\">Planes de sensibilización</mark> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> Desde la responsabilidad del <mark class=\"m-autoridad\">Gobierno del Estado</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y de <mark class=\"m-plazo\">manera <mark class=\"m-resp\" data-q=\"15-272,15-275\">inmediata</mark></mark> a la entrada en vigor de esta ley, con la consiguiente dotación presupuestaria, <mark class=\"m-accion\">se pondrá</mark> <mark class=\"m-personalizado\">en marcha un</mark> <mark class=\"m-destacable\">Plan</mark> <mark class=\"m-plazo\">Estatal</mark> <mark class=\"m-destacable\">de Sensibilización y Prevención de la Violencia de Género</mark> con carácter permanente que como <mark class=\"m-personalizado\">mínimo</mark> recoja los <mark class=\"m-personalizado\">siguientes elementos:</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"15-33\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>b)</b> Dirigido <mark class=\"m-personalizado\">tanto a hombres como a mujeres, desde un trabajo comunitario e intercultural,</mark> incluyendo el <mark class=\"m-personalizado\">ámbito</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de las tecnologías de la información y el digital.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-181\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>d)</b> Controlado por una <mark class=\"m-autoridad\">Comisión</mark> de amplia participación, que <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">creará</mark> en un <mark class=\"m-plazo\">plazo máximo de un</mark> <mark class=\"m-personalizado\">mes, en la que se ha de asegurar la presencia de las víctimas y su entorno, las instituciones, los profesionales y de</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">de reconocido prestigio social</mark> relacionado con el tratamiento de estos temas.  <mark class=\"m-resp ex-q\" data-q=\"15-47,15-ia-1010\">🎯 2 preguntas</mark></p><p>La Delegación del <mark class=\"m-autoridad\">Gobierno</mark> contra la <span class=\"ex-plg\"><span class=\"ex-plg-t\">Violencia de Género, oída la <mark class=\"m-autoridad\">Comisión</mark> a la que se refiere el párrafo anterior, <mark class=\"m-accion\">elaborará</mark> el Informe anual de evaluación del Plan Estatal de Sensibilización y Prevención de la Violencia</span></span> de Género y lo <mark class=\"m-accion\">remitirá</mark> <mark class=\"m-resp r-ia\" data-q=\"15-ia-1011\">a las Cortes Generales</mark>. <mark class=\"m-resp ex-q\" data-q=\"15-127,15-142\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-autoridad\">Los poderes públicos,</mark> en el marco de <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">sus competencias,</u></mark> <mark class=\"m-accion\">impulsarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">además campañas de información y sensibilización</u></mark></span></span> específicas con el fin de <mark class=\"m-resp\" data-q=\"15-287\">prevenir la violencia de género</mark>.</p><p data-ex=\"*\"><b>3.</b> <mark class=\"m-personalizado\">Las campañas</mark> de información y sensibilización <span class=\"ex-plg\"><span class=\"ex-plg-t\">contra esta forma de violencia <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">realizarán</mark> de manera que se <mark class=\"m-personalizado\">garantice</mark> el <mark class=\"m-personalizado\">acceso</mark> a las mismas de las <mark class=\"m-autoridad\">personas</mark> con <mark class=\"m-personalizado\">discapacidad.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-288,15-ia-1012\">🎯 2 preguntas</mark></p>"],["Artículo 4. <mark class=\"m-destacable\">Principios y valores del sistema educativo</mark> <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> El sistema educativo español <mark class=\"m-accion\">incluirá</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">entre sus <u class=\"m-clave\">fines</u> la formación</mark> en <mark class=\"m-personalizado\">el respeto</mark> de <mark class=\"m-personalizado\">los derechos y libertades fundamentales</mark> y de la <mark class=\"m-personalizado\">igualdad</mark> entre hombres y mujeres, así como en el ejercicio de la <mark class=\"m-personalizado\">tolerancia y de la libertad dentro</mark> de los <mark class=\"m-personalizado\">principios democráticos de convivencia.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-2322\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Igualmente,</mark> el sistema educativo español <mark class=\"m-accion\">incluirá,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">dentro de sus</mark> <mark class=\"m-destacable\">principios de calidad,</mark> la <mark class=\"m-personalizado\">eliminación de los obstáculos</mark> que dificultan la <mark class=\"m-personalizado\">plena igualdad</mark> entre hombres y mujeres y <mark class=\"m-personalizado\">la formación</mark> para la <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1013\">prevención de conflictos</mark> y para</mark> la <mark class=\"m-personalizado\">resolución pacífica</mark> de los mismos.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-73\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.</b> La <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"15-75\">Educación Infantil</mark></mark> <mark class=\"m-accion\">contribuirá</mark> <mark class=\"m-personalizado\">a desarrollar</mark> en la infancia el <mark class=\"m-personalizado\">aprendizaje en la <mark class=\"m-resp\" data-q=\"15-269\">resolución pacífica de conflictos</mark>.</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">La Educación Primaria</mark> <mark class=\"m-accion\">contribuirá</mark> <mark class=\"m-personalizado\">a desarrollar</mark> en el <span class=\"ex-plg\"><span class=\"ex-plg-t\">alumnado su <mark class=\"m-personalizado\">capacidad para</mark> <mark class=\"m-destacable\">adquirir</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">habilidades</u></mark> en la <mark class=\"m-personalizado\">resolución pacífica</mark> de conflictos <mark class=\"m-destacable\">y</mark> para <mark class=\"m-personalizado\">comprender y respetar la igualdad</mark> entre sexos.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-226\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>4.</b> La <mark class=\"m-resp\" data-q=\"15-39\">Educación Secundaria Obligatoria</mark> <mark class=\"m-accion\">contribuirá</mark> a desarrollar <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el alumnado la capacidad para relacionarse con los demás de forma pacífica y para conocer, valorar y respetar la igualdad de <span class=\"m-circulo\"><mark class=\"m-personalizado\">oportunidades</mark></span> de hombres y mujeres.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-261\">🎯 1 pregunta</mark></p><p><b>5.</b> El Bachillerato y la Formación <span class=\"ex-plg\"><span class=\"ex-plg-t\">Profesional <mark class=\"m-accion\">contribuirán</mark> a <mark class=\"m-personalizado\">desarrollar</mark> en el alumnado la <mark class=\"m-personalizado\">capacidad para</mark> <mark class=\"m-destacable\">consolidar</mark> <mark class=\"m-personalizado\">su <mark class=\"m-resp r-ia\" data-q=\"15-ia-1015\">madurez personal, social y moral</mark>, que les permita actuar de forma responsable y autónoma <u class=\"m-clave\">y</u> para analizar y <u class=\"m-clave\">valorar críticamente</u> las desigualdades</mark> de sexo y <mark class=\"m-personalizado\"><u class=\"m-clave\">fomentar</u></mark> la <mark class=\"m-personalizado\">igualdad real y <u class=\"m-clave\">efectiva</u></mark> entre hombres y mujeres.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-266,15-ia-1014\">🎯 2 preguntas</mark></p><p data-ex=\"EX\"><b>6.</b> La Enseñanza para las <mark class=\"m-autoridad\">personas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">adultas <mark class=\"m-accion\">incluirá</mark> entre sus objetivos desarrollar actividades en la resolución pacífica de conflictos y fomentar el <mark class=\"m-personalizado\">respeto a la dignidad</mark> de las <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">y</mark> a la igualdad entre hombres y mujeres.</span></span> </p><p><b>7.</b> Las Universidades <mark class=\"m-accion\">incluirán</mark> y <mark class=\"m-accion\">fomentarán</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en todos los ámbitos académicos la <mark class=\"m-personalizado\">formación, docencia e investigación <u class=\"m-clave\">en igualdad</u></mark> de género <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">no discriminación</u> de <u class=\"m-clave\">forma <mark class=\"m-resp r-ia\" data-q=\"15-ia-1016\">transversal</mark>.</u></mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"15-166\">🎯 1 pregunta</mark></p>"],["Artículo 5. Escolarización inmediata en caso de violencia de género","<p>Las Administraciones competentes <mark class=\"m-accion\">deberán</mark> <mark class=\"m-destacable\">prever</mark> la escolarización <mark class=\"m-resp r-ia\" data-q=\"15-ia-1017\">inmediata</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">los <mark class=\"m-personalizado\">hijos</mark> que se vean afectados por un <mark class=\"m-personalizado\"><u class=\"m-clave\">cambio de residencia</u> derivada</mark> de actos de <mark class=\"m-personalizado\">violencia de género.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"15-143,15-283\">🎯 2 preguntas</mark></p>"],["Artículo 6. Fomento de la igualdad","<p>Con el <mark class=\"m-personalizado\">fin</mark> de garantizar la <span class=\"ex-plg\"><span class=\"ex-plg-t\">efectiva <mark class=\"m-personalizado\">igualdad</mark> entre hombres y mujeres, las <mark class=\"m-autoridad\">Administraciones educativas</mark> <mark class=\"m-accion\">velarán</mark> para que en todos los <mark class=\"m-personalizado\">materiales educativos se eliminen los <mark class=\"m-resp r-ia\" data-q=\"15-ia-1018\">estereotipos sexistas o discriminatorios</mark></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> para que <mark class=\"m-personalizado\">fomenten el igual valor</mark> de hombres y mujeres.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-86\">🎯 1 pregunta</mark></p>"],["Artículo 7. Formación inicial y permanente del profesorado <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\">Las Administraciones educativas <mark class=\"m-accion\">adoptarán</mark> las medidas <span class=\"ex-plg\"><span class=\"ex-plg-t\">necesarias para que en los planes <mark class=\"m-destacable\">de</mark> formación inicial y permanente del profesorado se incluya una <mark class=\"m-destacable\">formación</mark> <mark class=\"m-personalizado\">específica en materia</mark> <mark class=\"m-destacable\">de igualdad,</mark> con el fin de asegurar que adquieren los <mark class=\"m-personalizado\">conocimientos y las técnicas necesarias</mark> que les habiliten para:</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-289\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>c)</b> <mark class=\"m-personalizado\">La detección precoz de la violencia</mark> en el ámbito familiar, <span class=\"ex-plg\"><span class=\"ex-plg-t\">especialmente <mark class=\"m-personalizado\">sobre la mujer y los hijos e hijas.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1019\">🎯 1 pregunta</mark></p>"],["Artículo 8. Participación en los Consejos Escolares","<p><mark class=\"m-accion\">Se adoptarán</mark> las medidas precisas para asegurar <span class=\"ex-plg\"><span class=\"ex-plg-t\">que <mark class=\"m-destacable\">los Consejos Escolares</mark> <mark class=\"m-personalizado\">impulsen</mark> la adopción de medidas educativas que <mark class=\"m-personalizado\">fomenten la igualdad real y efectiva</mark> entre hombres y mujeres. Con el mismo fin, en <mark class=\"m-autoridad\">el Consejo Escolar del Estado</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">asegurará</mark> <mark class=\"m-personalizado\">la representación del</mark> <mark class=\"m-destacable\">Instituto de la Mujer</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u> de</mark> las <mark class=\"m-personalizado\">organizaciones</mark> que defiendan los intereses de las mujeres, <mark class=\"m-personalizado\">con implantación en todo el territorio</mark> nacional.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-171,15-ia-1020\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\">Artículo 9. Actuación de la inspección educativa: <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1021\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 11","<p><mark class=\"m-autoridad\">El Ente público</mark> al que corresponda <mark class=\"m-personalizado\">velar</mark> para <span class=\"ex-plg\"><span class=\"ex-plg-t\">que los medios audiovisuales cumplan sus obligaciones <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">las medidas</mark> que procedan <mark class=\"m-personalizado\">para asegurar</mark> un tratamiento de la mujer conforme con <mark class=\"m-personalizado\">los <mark class=\"m-resp\" data-q=\"15-233,15-ia-1023\">principios y valores constitucionales</mark>,</mark> sin perjuicio de las posibles actuaciones por parte de otras entidades.</span></span></p>"],["Artículo 12. <mark class=\"m-destacable\">Titulares de la acción de cesación</mark> y <mark class=\"m-destacable\">rectificación</mark> <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><mark class=\"m-autoridad\">La Delegación Especial del Gobierno contra la Violencia sobre la Mujer</mark> , <mark class=\"m-autoridad\">el Instituto de la Mujer u órgano</mark> equivalente <u class=\"m-clave\">de</u> cada <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Comunidad Autónoma, el Ministerio Fiscal y las Asociaciones</mark> <mark class=\"m-personalizado\">que tengan como objetivo <u class=\"m-clave\">único</u> la defensa</mark> de los intereses de <mark class=\"m-personalizado\">la mujer</mark> <mark class=\"m-accion\">estarán legitimados</mark> <mark class=\"m-personalizado\">para</mark> ejercitar <mark class=\"m-personalizado\">ante</mark> <mark class=\"m-autoridad\">los Tribunales</mark> <mark class=\"m-destacable\">la acción de cesación</mark> de <mark class=\"m-personalizado\">publicidad ilícita</mark> por utilizar en <mark class=\"m-personalizado\">forma vejatoria la imagen</mark> de la mujer, en los términos de la Ley 34/1988, de 11 de noviembre, General de Publicidad.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-8,15-144,15-ia-1024\">🎯 3 preguntas</mark></p>"],["Artículo 13. Medios de comunicación","<p><b>1.</b> <mark class=\"m-autoridad\">Las <mark class=\"m-resp\" data-q=\"15-77\">Administraciones Públicas</mark></mark> <mark class=\"m-accion\">velarán</mark> por el cumplimiento <span class=\"ex-plg\"><span class=\"ex-plg-t\">estricto de la legislación en lo relativo a la <mark class=\"m-personalizado\">protección y salvaguarda de los derechos fundamentales, con especial atención</mark> a <mark class=\"m-personalizado\">la erradicación</mark> de conductas favorecedoras de situaciones de <mark class=\"m-personalizado\">desigualdad</mark> de las mujeres en todos los <mark class=\"m-personalizado\">medios de comunicación social,</mark> de acuerdo con la legislación vigente.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1025\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-autoridad\">La Administración pública</mark> <mark class=\"m-accion\">promoverá</mark> <mark class=\"m-personalizado\">acuerdos de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1026\">autorregulación</mark></mark> que, contando <span class=\"ex-plg\"><span class=\"ex-plg-t\">con mecanismos de <mark class=\"m-personalizado\">control preventivo y de resolución extrajudicial</mark> de controversias eficaces, contribuyan al cumplimiento de la legislación publicitaria.</span></span></p>"],["Artículo 14 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-autoridad\">Los medios de comunicación</mark> <mark class=\"m-accion\"><mark class=\"m-resp\" data-q=\"15-46\">fomentarán</mark></mark> <mark class=\"m-personalizado\">la protección y salvaguarda de la <u class=\"m-clave\">igualdad</u></mark> entre hombre y mujer, <mark class=\"m-personalizado\">evitando</mark> toda <mark class=\"m-personalizado\">discriminación</mark> entre ellos.</p><p data-ex=\"EXOF\"><mark class=\"m-personalizado\">La difusión de informaciones</mark> relativas a la <mark class=\"m-destacable\">violencia</mark> sobre <span class=\"ex-plg\"><span class=\"ex-plg-t\">la <mark class=\"m-personalizado\">mujer</mark> <mark class=\"m-accion\">garantizará,</mark> con la correspondiente objetividad informativa, <mark class=\"m-personalizado\">la defensa</mark> de los <mark class=\"m-personalizado\">derechos humanos, la libertad y dignidad</mark> de las <mark class=\"m-personalizado\">mujeres víctimas</mark> de violencia <mark class=\"m-personalizado\">y</mark> de sus <mark class=\"m-personalizado\">hijos. En particular,</mark> <mark class=\"m-accion\">se tendrá</mark> especial <mark class=\"m-personalizado\">cuidado</mark> en el <mark class=\"m-personalizado\">tratamiento gráfico</mark> de las informaciones.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-290,15-ia-1027\">🎯 2 preguntas</mark></p>"],["Artículo 15. <mark class=\"m-destacable\">Sensibilización</mark> y formación <span class=\"ex-sello\">✱</span>","<p><b>1.</b> <mark class=\"m-autoridad\">Las Administraciones sanitarias,</mark> <mark class=\"m-personalizado\">en el seno del</mark> <mark class=\"m-autoridad\">Consejo Interterritorial del Sistema Nacional de</mark> Salud, <mark class=\"m-accion\">promoverán</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">e <mark class=\"m-accion\">impulsarán</mark> actuaciones de los profesionales sanitarios para la <mark class=\"m-destacable\">detección</mark> precoz de la violencia de género y <mark class=\"m-accion\">propondrán</mark> <mark class=\"m-personalizado\">las medidas</mark> que estimen necesarias a <mark class=\"m-personalizado\">fin</mark> de optimizar la contribución del sector sanitario en la <mark class=\"m-personalizado\">lucha</mark> contra este tipo de violencia.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-103,15-122,15-253,15-ia-1028\">🎯 4 preguntas</mark></p><p data-ex=\"*\"><b><mark class=\"m-personalizado\">2.</mark></b> <mark class=\"m-personalizado\">En particular, se</mark> <mark class=\"m-accion\">desarrollarán</mark> <mark class=\"m-personalizado\">programas</mark> de sensibilización <span class=\"ex-plg\"><span class=\"ex-plg-t\">y formación continuada del personal sanitario con el fin de mejorar e impulsar el diagnóstico precoz, la asistencia y la rehabilitación de la mujer en las situaciones de violencia de género a que se refiere esta Ley.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-24\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-autoridad\">Las Administraciones educativas</mark> competentes <mark class=\"m-accion\">asegurarán</mark> que en <span class=\"ex-plg\"><span class=\"ex-plg-t\">los ámbitos curriculares de las <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1029\">licenciaturas y diplomaturas</mark>, y en los programas de especialización de las profesiones sociosanitarias, se incorporen contenidos dirigidos a la capacitación para la prevención, la detección</mark> precoz, intervención y apoyo a las víctimas de esta forma de violencia.</span></span></p>"],["Artículo 16. <mark class=\"m-autoridad\">Consejo</mark> Interterritorial del Sistema Nacional de Salud <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R3</span>","<p data-ex=\"EX\"><mark class=\"m-personalizado\">En el seno del</mark> <mark class=\"m-autoridad\">Consejo Interterritorial del Sistema Nacional de Salud</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">constituirá,</mark> <mark class=\"m-plazo\">en el plazo de un año desde la entrada en vigor de la presente Ley, una</mark> <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-plazo\">contra la Violencia de Género que apoye técnicamente y oriente</mark> la planificación de las medidas sanitarias contempladas en este capítulo, <mark class=\"m-personalizado\">evalúe y proponga</mark> las necesarias para la aplicación del protocolo sanitario y cualesquiera otras medidas que se estimen precisas para que el sector sanitario <mark class=\"m-personalizado\">contribuya a la</mark> erradicación de esta forma de violencia.</span></span> </p><p data-ex=\"*\"><mark class=\"m-autoridad\">La Comisión contra la Violencia de Género del Consejo</mark> <mark class=\"m-personalizado\">Interterritorial del Sistema Nacional de Salud</mark> <mark class=\"m-accion\">estará compuesta</mark> <mark class=\"m-personalizado\">por <mark class=\"m-resp\" data-q=\"15-256,15-ia-1030\">representantes de todas las Comunidades Autónomas con competencia en la materia</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"15-129\">🎯 1 pregunta</mark></p><p data-ex=\"EX\" data-r=\"R3\"><span class=\"ex-sello ex-sello-r\">R3</span> La <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-accion\">emitirá</mark> un <mark class=\"m-destacable\">informe anual</mark> <mark class=\"m-personalizado\">que</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">será remitido</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Observatorio Estatal de la Violencia sobre la Mujer y al Pleno del Consejo Interterritorial.</mark></span></span> </p>"],["Artículo 17. Garantía de los derechos de las víctimas <span class=\"ex-sello\">EXOF</span>","<p><b><mark class=\"m-autoridad\">1.</mark></b> <mark class=\"m-autoridad\">Todas las mujeres víctimas</mark> de violencia de género <span class=\"ex-plg\"><span class=\"ex-plg-t\">tienen <mark class=\"m-personalizado\">garantizados los derechos</mark> reconocidos en esta <mark class=\"m-personalizado\">ley, sin que pueda existir <mark class=\"m-resp r-ia\" data-q=\"15-ia-1031\">discriminación</mark> en el acceso a los mismos.</mark></span></span></p><p data-ex=\"EXOF\"><b>2.</b> <mark class=\"m-destacable\">La información,</mark> la <mark class=\"m-destacable\">asistencia social integral</mark> y la <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">asistencia jurídica</mark> a las víctimas de la violencia de género, en los términos regulados en</span></span> este capítulo, contribuyen a <mark class=\"m-personalizado\">hacer reales y efectivos sus derechos constitucionales</mark> <mark class=\"m-resp\" data-q=\"15-276,15-ia-1032\">a la <mark class=\"m-destacable\">integridad física y moral,</mark> a la <mark class=\"m-destacable\">libertad y seguridad</mark> y a la <mark class=\"m-destacable\">igualdad y no discriminación</mark> por <mark class=\"m-personalizado\">razón de</mark> sexo</mark>. <mark class=\"m-resp ex-q\" data-q=\"15-132\">🎯 1 pregunta</mark></p><p><b>3.</b> Los servicios de información y orientación, atención psicosocial inmediata, telefónica y en línea, asesoramiento jurídico 24 horas, los servicios de acogida y asistencia social integral, consistentes en orientación jurídica, psicológica y social destinadas a las víctimas de violencias contra las mujeres <mark class=\"m-accion\">tendrán</mark> carácter de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1033\">servicios esenciales</mark>.</p><p>Igualmente, <mark class=\"m-accion\">se garantizará</mark> el normal funcionamiento y <span class=\"ex-plg\"><span class=\"ex-plg-t\">prestación del sistema de seguimiento por medios telemáticos del cumplimiento de las</span></span> medidas cautelares y penas de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1034\">prohibición de aproximación en materia de violencia de género</mark>.</p></div></div><div class=\"ex-linea\">Artículo 18. <mark class=\"m-personalizado\">Derecho</mark> a <mark class=\"m-personalizado\">la información</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1035,15-ia-1036\">🎯 2 preguntas más de este artículo</mark>"],["Artículo <mark class=\"m-plazo\">19.</mark> Derecho a la atención integral <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> Las mujeres víctimas de violencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">de género tienen derecho a servicios sociales de <mark class=\"m-destacable\">atención,</mark> de emergencia, de <mark class=\"m-destacable\">apoyo y acogida</mark> y de <mark class=\"m-destacable\">recuperación integral.</mark> La organización de estos servicios por parte de las comunidades autónomas y <mark class=\"m-destacable\">las Corporaciones</mark> Locales <mark class=\"m-accion\">responderá</mark> a los principios de <mark class=\"m-destacable\">atención permanente, actuación urgente,</mark> especialización de <mark class=\"m-destacable\">prestaciones y multidisciplinariedad profesional.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-64,15-66,15-120,15-123,15-ia-1037,15-19\">🎯 6 preguntas</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>a)</b> <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"15-293\">Información a las víctimas</mark>.</mark></p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los servicios <mark class=\"m-accion\">adoptarán</mark> fórmulas organizativas que, por la especialización de su personal, por sus características de convergencia e integración de acciones, garanticen la efectividad de los indicados principios, asegurando, en todo caso, la disponibilidad, accesibilidad y calidad de los mismos.</span></span> En todo caso, <mark class=\"m-accion\">se procurará</mark> una distribución <span class=\"ex-plg\"><span class=\"ex-plg-t\">territorial equitativa de los servicios y <mark class=\"m-accion\">se garantizará</mark> su accesibilidad</span></span> a las mujeres de las <mark class=\"m-resp r-ia\" data-q=\"15-ia-1039\">zonas rurales y otras zonas alejadas</mark>.</p><p><b>4.</b> Estos servicios <mark class=\"m-accion\">actuarán</mark> coordinadamente y <span class=\"ex-plg\"><span class=\"ex-plg-t\">en colaboración con los Cuerpos de Seguridad, los Juzgados de Violencia sobre la Mujer, los servicios sanitarios y las instituciones encargadas de prestar asistencia jurídica a las víctimas del ámbito geográfico correspondiente. Estos servicios <mark class=\"m-accion\">podrán solicitar</mark> al <mark class=\"m-autoridad\">órgano</mark> judicial las medidas urgentes que consideren necesarias.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-156\">🎯 1 pregunta</mark></p><p><b>5.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">También <mark class=\"m-accion\">tendrán</mark> derecho a la asistencia social integral a través de estos servicios sociales los <mark class=\"m-autoridad\">menores</mark> que se encuentren bajo la patria potestad o guarda y custodia de la <mark class=\"m-autoridad\">persona</mark> agredida, o convivan en contextos familiares en los que se cometen actos de violencia de género. A estos efectos, los servicios sociales <mark class=\"m-accion\">deberán contar</mark> con personal específicamente formado para atender a los <mark class=\"m-autoridad\">menores,</mark> con el fin de prevenir y evitar de forma eficaz las situaciones que puedan comportar daños psíquicos y físicos a los <mark class=\"m-autoridad\">menores</mark> que viven en entornos familiares donde existe violencia de género.</span></span> En particular, <mark class=\"m-accion\">deberán contar</mark> con profesionales de <span class=\"ex-plg\"><span class=\"ex-plg-t\">la psicología infantil para la atención de las hijas e hijos <mark class=\"m-autoridad\">menores</mark> víctimas de</span></span> violencia de género, incluida la <mark class=\"m-resp r-ia\" data-q=\"15-ia-1040\">violencia vicaria</mark>.</p></div></div><div class=\"ex-linea\">Artículo 19 bis. <mark class=\"m-personalizado\">Derecho</mark> a la <mark class=\"m-destacable\">atención</mark> sanitaria: <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1041,15-ia-1042\">🎯 2 preguntas más de este artículo</mark>"],["<mark class=\"m-plazo\">Artículo 20.</mark> Asistencia jurídica <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><b>1.</b> Las víctimas de violencia de <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">género tienen derecho a recibir</mark> <mark class=\"m-destacable\">asesoramiento jurídico gratuito</mark> en el <mark class=\"m-personalizado\">momento <mark class=\"m-resp r-ia\" data-q=\"15-ia-1043\">inmediatamente previo</mark></mark> a la interposición de la denuncia, y a la <mark class=\"m-destacable\">defensa y representación gratuitas por</mark> <mark class=\"m-autoridad\">abogado</mark> <mark class=\"m-destacable\">y procurador</mark> en <mark class=\"m-personalizado\">todos los procesos y procedimientos administrativos</mark> que tengan <mark class=\"m-destacable\">causa</mark> <mark class=\"m-personalizado\">directa o indirecta</mark> <mark class=\"m-destacable\">en</mark> la violencia padecida.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">En estos supuestos, una <mark class=\"m-destacable\">misma dirección letrada</mark> <mark class=\"m-accion\">deberá asumir</mark> la defensa de la víctima, siempre que con ello se garantice debidamente su derecho de defensa.</span></span> Este derecho <mark class=\"m-accion\">asistirá</mark> también a los causahabientes en caso de fallecimiento de la víctima, siempre que <mark class=\"m-resp r-ia\" data-q=\"15-ia-1044\">no fueran partícipes en los hechos</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">En todo caso, <mark class=\"m-accion\">se garantizará</mark> la defensa jurídica, gratuita y especializada de forma inmediata a todas las víctimas de violencia de género que lo soliciten.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-294\">🎯 1 pregunta</mark></p><p><b>5.</b> Los Colegios de Procuradores <mark class=\"m-accion\">adoptarán</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">las medidas necesarias para la designación urgente de procurador o procuradora en los procedimientos que se sigan por violencia de género cuando la víctima desee personarse como acusación particular.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1045\">🎯 1 pregunta</mark></p><p><b>7.</b> Las víctimas de violencia de <span class=\"ex-plg\"><span class=\"ex-plg-t\">género <mark class=\"m-accion\">podrán personarse</mark> como acusación particular en cualquier momento del procedimiento si bien ello <mark class=\"m-accion\">no permitirá retrotraer</mark> ni reiterar las actuaciones ya practicadas antes de su personación, <mark class=\"m-accion\">ni podrá suponer</mark> una merma del derecho de defensa del acusado.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1046\">🎯 1 pregunta</mark></p>"],["<mark class=\"m-autoridad\">Artículo</mark> 21. Derechos laborales y de Seguridad Social <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R4</span>","<p data-ex=\"EX\" data-r=\"R4\"><span class=\"ex-sello ex-sello-r\">R4</span> <b>1.</b> La <mark class=\"m-personalizado\">trabajadora víctima</mark> de violencia de <span class=\"ex-plg\"><span class=\"ex-plg-t\">género <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">derecho,</mark> en los términos previstos en el Estatuto de <mark class=\"m-autoridad\">los Trabajadores,</mark> a la reducción <mark class=\"m-personalizado\">o</mark> a <mark class=\"m-personalizado\">la reordenación</mark> de su tiempo de trabajo, <mark class=\"m-personalizado\">a</mark> la <mark class=\"m-personalizado\">movilidad geográfica,</mark> al <mark class=\"m-personalizado\">cambio</mark> de <mark class=\"m-personalizado\">centro de</mark> trabajo, a la <mark class=\"m-personalizado\">adaptación</mark> de su puesto de trabajo y a los apoyos que precise por razón de su discapacidad para su <mark class=\"m-personalizado\">reincorporación,</mark> a la <mark class=\"m-destacable\">suspensión de la relación laboral con reserva</mark> de puesto de trabajo y a la extinción del contrato de trabajo.</span></span> </p><p><b><mark class=\"m-autoridad\">3.</mark></b> <mark class=\"m-autoridad\">Las empresas que formalicen</mark> <mark class=\"m-destacable\">contratos de interinidad,</mark> para <mark class=\"m-personalizado\">sustituir a trabajadoras víctimas</mark> de violencia de género que hayan suspendido su contrato de trabajo o ejercitado su derecho <mark class=\"m-destacable\">a la</mark> <mark class=\"m-personalizado\">movilidad geográfica o al cambio de centro de</mark> trabajo, <mark class=\"m-accion\">tendrán</mark> derecho a una <mark class=\"m-destacable\">bonificación del 100 por</mark> 100 de las cuotas empresariales a la <mark class=\"m-autoridad\">Seguridad Social</mark> por contingencias comunes, <mark class=\"m-autoridad\">durante todo el período de</mark> <mark class=\"m-plazo\">suspensión</mark> <mark class=\"m-autoridad\">de la trabajadora sustituida</mark> o <mark class=\"m-plazo\">durante seis meses</mark> <span class=\"m-caja\">en</span> los supuestos de <mark class=\"m-personalizado\">movilidad geográfica</mark> o <mark class=\"m-personalizado\">cambio de centro de trabajo.</mark> Cuando se produzca la reincorporación, ésta <mark class=\"m-accion\">se realizará</mark> en las mismas condiciones existentes en el momento de la suspensión del contrato de trabajo, garantizándose los ajustes razonables que se puedan precisar por razón de discapacidad.  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1047\">🎯 1 pregunta</mark></p><p><b>4.</b> Las <mark class=\"m-destacable\">ausencias o faltas de puntualidad</mark> al trabajo motivadas <span class=\"ex-plg\"><span class=\"ex-plg-t\">por la situación física o psicológica derivada de la violencia de género <mark class=\"m-destacable\">se</mark> <mark class=\"m-accion\">considerarán</mark> <mark class=\"m-destacable\">justificadas y</mark> <mark class=\"m-accion\">serán remuneradas,</mark></span></span> cuando así lo determinen los <mark class=\"m-resp r-ia\" data-q=\"15-ia-1048\">servicios sociales de atención o servicios de salud, según proceda</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">sin perjuicio de que dichas ausencias sean comunicadas</span></span> por la trabajadora a la <mark class=\"m-resp r-ia\" data-q=\"15-ia-2240\">empresa a la mayor brevedad</mark>. <mark class=\"m-resp ex-q\" data-q=\"15-322\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>5.</b> A las trabajadoras por cuenta <span class=\"ex-plg\"><span class=\"ex-plg-t\">propia víctimas de violencia de género que cesen en su actividad para hacer efectiva su protección o su derecho a la asistencia social integral, se les <mark class=\"m-accion\">considerará</mark> en situación de cese temporal de la actividad en los términos previstos en el texto refundido de la Ley General de la Seguridad Social, aprobado por el Real Decreto Legislativo 8/2015, de 30 de octubre, y se les</span></span> <mark class=\"m-accion\">suspenderá</mark> la obligación de cotización <mark class=\"m-resp\" data-q=\"15-38\">durante un período de seis meses</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">que les <mark class=\"m-accion\">serán considerados</mark> como de cotización efectiva a efectos de las prestaciones de Seguridad Social.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">Asimismo, su situación <mark class=\"m-accion\">será considerada</mark> como asimilada al alta.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-61,15-114,15-ia-2241\">🎯 3 preguntas</mark></p></div></div><div class=\"ex-linea\">Artículo 22. Programa específico de empleo: <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1050\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 23. Acreditación de situaciones de violencia de género <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EXOF\">Las situaciones de violencia de género <span class=\"ex-plg\"><span class=\"ex-plg-t\">que dan lugar al reconocimiento de los <mark class=\"m-personalizado\">derechos</mark> regulados en esta ley <mark class=\"m-accion\">se acreditarán</mark> <mark class=\"m-personalizado\">mediante</mark> una <mark class=\"m-destacable\">sentencia condenatoria</mark> por cualquiera de las manifestaciones de la violencia contra las mujeres previstas en esta ley, <mark class=\"m-destacable\">una orden de protección</mark> o <mark class=\"m-destacable\">cualquier otra resolución judicial</mark> que acuerde una medida cautelar a favor de la víctima, <mark class=\"m-personalizado\">o bien por el informe</mark> del <mark class=\"m-autoridad\">Ministerio Fiscal</mark> que indique la existencia de indicios de que la demandante es víctima de violencia de género. También <mark class=\"m-accion\">podrán acreditarse</mark> las situaciones de violencia contra las mujeres mediante <mark class=\"m-destacable\">informe de los servicios sociales,</mark> de los <mark class=\"m-destacable\">servicios especializados,</mark> o de <mark class=\"m-destacable\">los servicios de acogida de la Administración Pública competente</mark> destinados a las víctimas de violencia de género, o por cualquier otro título, siempre que ello esté previsto en las disposiciones normativas de carácter sectorial que regulen el acceso a cada uno de los derechos y recursos.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1051\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><mark class=\"m-autoridad\">El Gobierno y las</mark> comunidades <mark class=\"m-autoridad\">autónomas,</mark> en el marco <span class=\"ex-plg\"><span class=\"ex-plg-t\">de la <mark class=\"m-autoridad\">Conferencia Sectorial de Igualdad,</mark> <mark class=\"m-accion\">diseñarán,</mark> de común <mark class=\"m-autoridad\">acuerdo,</mark> los procedimientos básicos que permitan poner en marcha los sistemas de <mark class=\"m-destacable\">acreditación</mark> de las situaciones de <mark class=\"m-destacable\">violencia</mark> de género.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-62\">🎯 1 pregunta</mark></p>"],["Artículo 24. Ámbito de los derechos","<p>La <mark class=\"m-personalizado\">funcionaria víctima</mark> de violencia de género <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">derecho a la <u class=\"m-clave\">reducción</u> o a la reordenación</mark> de su <mark class=\"m-personalizado\">tiempo</mark> de trabajo, a la <span class=\"m-circulo\"><mark class=\"m-personalizado\">movilidad</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">geográfica</u></mark> de centro de trabajo y a la <span class=\"m-circulo\"><mark class=\"m-personalizado\">excedencia</mark></span> en los</span></span> términos que se determinen en <mark class=\"m-resp r-ia\" data-q=\"15-ia-1101\">su legislación específica</mark>. <mark class=\"m-resp ex-q\" data-q=\"15-80\">🎯 1 pregunta</mark></p>"],["Artículo 25. Justificación de las <mark class=\"m-personalizado\">faltas de asistencia</mark>","<p><mark class=\"m-personalizado\">Las <u class=\"m-clave\">ausencias totales</u> o <u class=\"m-clave\">parciales</u></mark> al trabajo <mark class=\"m-personalizado\">motivadas</mark> por la <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">situación física</mark> o <mark class=\"m-personalizado\">psicológica derivada</mark> de <mark class=\"m-personalizado\">la</mark> violencia de género sufrida <u class=\"m-clave\">por una</u> mujer funcionaria <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">considerarán</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1102\">justificadas</mark> en los términos</mark> que <mark class=\"m-personalizado\">se determine en su</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">legislación</u> específica.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"15-135\">🎯 1 pregunta</mark></p>"],["Artículo 27. <mark class=\"m-destacable\">Ayudas sociales</mark> <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R5</span>","<p data-ex=\"*\"><b>1.</b> Cuando las víctimas de violencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">de género <mark class=\"m-destacable\">careciesen</mark> de <mark class=\"m-personalizado\">rentas</mark> <mark class=\"m-destacable\">superiores,</mark> <mark class=\"m-personalizado\">en cómputo mensual,</mark> <mark class=\"m-destacable\">al 75 <u class=\"m-clave\">por</u> 100</mark> del <mark class=\"m-personalizado\">salario mínimo</mark> interprofesional, excluida la parte proporcional de <mark class=\"m-personalizado\">dos pagas extraordinarias,</mark> <mark class=\"m-accion\">recibirán</mark> una ayuda de <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1103\">pago único</mark>,</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">siempre</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">que</u> se</mark> presuma que debido <mark class=\"m-personalizado\">a</mark> su <mark class=\"m-personalizado\">edad, falta de preparación</mark> general o especializada y <mark class=\"m-personalizado\">circunstancias sociales,</mark> la víctima <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">especiales dificultades</mark> para <mark class=\"m-personalizado\">obtener un empleo <u class=\"m-clave\">y</u></mark> por dicha <mark class=\"m-personalizado\">circunstancia</mark> <mark class=\"m-accion\">no participará</mark> en los <mark class=\"m-personalizado\">programas de empleo</mark> establecidos para su inserción profesional.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-58,15-145,15-250,15-284,15-ia-1104\">🎯 5 preguntas</mark></p><p><b>3.</b> Estas ayudas, financiadas con cargo <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">a los Presupuestos Generales del</mark> <mark class=\"m-autoridad\">Estado,</mark> <mark class=\"m-accion\">serán concedidas</mark> por las <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1106\">Administraciones competentes en materia de servicios sociales</mark>.</mark> <mark class=\"m-personalizado\">En la tramitación del procedimiento de concesión,</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">incorporarse informe del Servicio Público de Empleo referido a la previsibilidad de que por las circunstancias a las que se refiere</mark> el apartado 1 de este artículo, la aplicación del programa de empleo no incida</span></span> de forma sustancial en la <mark class=\"m-resp r-ia\" data-q=\"15-ia-1107\">mejora de la <mark class=\"m-personalizado\">empleabilidad</mark> de la víctima</mark>.</p><p data-ex=\"EXOF\"><b>4.</b> En el caso de que la víctima tenga <mark class=\"m-personalizado\">responsabilidades</mark> <mark class=\"m-accion\">familiares, su importe podrá alcanzar el</mark> de un período equivalente al de <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1108\">18 meses</mark></mark> de subsidio, o de 24 meses si la víctima o alguno de los <mark class=\"m-personalizado\"><u class=\"m-clave\">familiares</u> que <u class=\"m-clave\">conviven</u></mark> con ella tiene reconocida <mark class=\"m-personalizado\">oficialmente</mark> una <mark class=\"m-personalizado\">minusvalía</mark> en grado <mark class=\"m-personalizado\">igual o superior al 33 por 100,</mark> en los términos que establezcan las disposiciones de desarrollo de la presente Ley. <mark class=\"m-resp ex-q\" data-q=\"15-265\">🎯 1 pregunta</mark></p><p><b>5.</b> <mark class=\"m-personalizado\">Estas <u class=\"m-clave\">ayudas</u></mark> <mark class=\"m-accion\">serán</mark> compatibles con cualquiera <span class=\"ex-plg\"><span class=\"ex-plg-t\">de las previstas en la <mark class=\"m-personalizado\">Ley 35/1995,</mark> de 11 de diciembre, de Ayudas y Asistencia a las Víctimas de Delitos Violentos y contra la</span></span> Libertad Sexual, así como con <mark class=\"m-resp r-ia\" data-q=\"15-ia-1109\">cualquier otra ayuda económica de carácter autonómico o local concedida por la situación de violencia de género</mark>.</p>"],["<mark class=\"m-plazo\">Artículo 28.</mark> Acceso a la vivienda y residencias públicas para mayores <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R6</span>","<p data-ex=\"EXOF\" data-r=\"R6\"><span class=\"ex-sello ex-sello-r\">R6</span> Las mujeres víctimas de violencia de género <mark class=\"m-accion\">serán consideradas</mark> colectivos prioritarios <mark class=\"m-resp\" data-q=\"15-167\">en el acceso a viviendas protegidas y residencias públicas para mayores</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los términos que determine la legislación aplicable.</span></span></p>"],["<mark class=\"m-plazo\">Artículo 28 bis.</mark> Alcance y garantía del derecho","<p>Las víctimas de violencia de género <span class=\"ex-plg\"><span class=\"ex-plg-t\">tienen derecho a la reparación, lo que comprende la compensación económica por los daños y perjuicios derivados de la violencia, las medidas necesarias para su completa recuperación física, psíquica y social, las acciones</span></span> de reparación simbólica y las <mark class=\"m-resp\" data-q=\"15-324,15-ia-1111,15-ia-2249\">garantías de no repetición</mark>.</p>"],["Artículo 30. <mark class=\"m-destacable\">Observatorio Estatal de Violencia sobre la Mujer</mark> <span class=\"ex-sello\">✱</span>","<p><b>2.</b> El <mark class=\"m-autoridad\">Observatorio Estatal de Violencia sobre la</mark> Mujer <mark class=\"m-accion\">remitirá</mark> <mark class=\"m-personalizado\">al</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Gobierno</mark> y a las <mark class=\"m-autoridad\">Comunidades Autónomas,</mark> <mark class=\"m-plazo\"><mark class=\"m-resp\" data-q=\"15-105\">con periodicidad anual</mark>, un informe sobre la evolución de la violencia</mark> ejercida sobre la mujer en los términos a que se refiere <u class=\"m-clave\">el</u> artículo 1 de la presente Ley, <mark class=\"m-personalizado\">con determinación</mark> de los <mark class=\"m-personalizado\">tipos penales</mark> que se hayan <mark class=\"m-personalizado\">aplicado, y</mark> de la <mark class=\"m-personalizado\">efectividad de las medidas</mark> acordadas para la protección de las víctimas.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">El informe <mark class=\"m-accion\">destacará</mark> <mark class=\"m-personalizado\">asimismo las necesidades de reforma legal</mark> con objeto de garantizar que la aplicación de las medidas de protección adoptadas puedan asegurar el máximo nivel de tutela para las mujeres.</span></span> <mark class=\"m-resp ex-q\" data-q=\"15-150\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>3.</b> <mark class=\"m-personalizado\">Reglamentariamente se</mark> <mark class=\"m-accion\">determinarán</mark> <mark class=\"m-personalizado\">sus funciones, su régimen de funcionamiento</mark> y <mark class=\"m-personalizado\">su <u class=\"m-clave\">composición,</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en la que <mark class=\"m-accion\">se garantizará,</mark> en <mark class=\"m-personalizado\">todo caso,</mark> la <mark class=\"m-personalizado\">participación de</mark> las <mark class=\"m-personalizado\">Comunidades Autónomas,</mark> las <mark class=\"m-personalizado\">entidades locales,</mark> los <mark class=\"m-personalizado\">agentes sociales,</mark> las <mark class=\"m-personalizado\">asociaciones de consumidores y usuarios,</mark> y las <mark class=\"m-personalizado\">organizaciones de mujeres con implantación en todo el territorio</mark> del <mark class=\"m-autoridad\">Estado</mark> así como de las <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"15-42\">organizaciones empresariales y sindicales más representativas</mark>.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1121\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\">Artículo 31. <mark class=\"m-autoridad\">Fuerzas y Cuerpos de Seguridad</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1122,15-ia-1123,15-ia-1124,15-ia-1125\">🎯 4 preguntas más de este artículo</mark>"],["Artículo 32. <mark class=\"m-destacable\">Planes de colaboración</mark> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-autoridad\">Los poderes públicos</mark> <mark class=\"m-accion\">elaborarán</mark> <mark class=\"m-destacable\">planes de colaboración</mark> <mark class=\"m-personalizado\">que garanticen <u class=\"m-clave\">la ordenación</u> de sus actuaciones en</mark> la <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">prevención, asistencia</u> y <u class=\"m-clave\">persecución</u></mark> de los actos de violencia de género, que <mark class=\"m-accion\">deberán implicar</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">las administraciones sanitarias, <u class=\"m-clave\">la</u> Administración de Justicia,</mark> las Fuerzas <u class=\"m-clave\">y</u> Cuerpos de Seguridad <mark class=\"m-personalizado\">y</mark> los <mark class=\"m-autoridad\">servicios sociales y organismos de igualdad.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-251,15-280\">🎯 2 preguntas</mark></p><p><b>2.</b> En desarrollo de dichos planes, <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">se articularán</mark> protocolos de actuación que determinen los procedimientos que aseguren una actuación global e integral de las distintas administraciones y servicios implicados,</span></span> y que garanticen la actividad <mark class=\"m-resp r-ia\" data-q=\"15-ia-1126\">probatoria</mark> en <span class=\"ex-plg\"><span class=\"ex-plg-t\">los procesos que se sigan.</span></span></p><p><b>3.</b> Las administraciones con competencias sanitarias <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">promoverán</mark> la aplicación, permanente actualización y difusión de protocolos que contengan pautas uniformes de actuación sanitaria, tanto en el ámbito público como</span></span> privado, y en especial, del <mark class=\"m-resp\" data-q=\"15-273,15-ia-1127\">Protocolo aprobado por el <mark class=\"m-autoridad\">Consejo</mark> Interterritorial del Sistema Nacional de Salud</mark>.</p><p>Los protocolos, además de referirse a <span class=\"ex-plg\"><span class=\"ex-plg-t\">los procedimientos a seguir, <mark class=\"m-accion\">harán</mark> referencia expresa</span></span> a las relaciones con la <mark class=\"m-resp r-ia\" data-q=\"15-ia-1128\">Administración de Justicia, en aquellos casos en que exista constatación o sospecha fundada de daños físicos o psíquicos ocasionados por estas agresiones o abusos</mark>.</p><p><b><mark class=\"m-plazo\">4.</mark></b> En las actuaciones previstas en <span class=\"ex-plg\"><span class=\"ex-plg-t\">este artículo <mark class=\"m-accion\">se considerará</mark> de forma especial la situación de las mujeres que, por sus circunstancias personales y sociales puedan tener mayor riesgo de sufrir la violencia de género o mayores dificultades para acceder a los servicios previstos en esta ley, tales como las pertenecientes a minorías, las inmigrantes, las que se encuentran en situación de exclusión social, las mujeres con discapacidad, las mujeres mayores o</span></span> aquellas que viven en el <mark class=\"m-resp r-ia\" data-q=\"15-ia-1129\">ámbito rural</mark>.</p>"],["ARTÍCULO 40 <span class=\"ex-sello\">✱</span>","<p><b>1.</b> Constituye el <mark class=\"m-destacable\">objeto</mark> del <mark class=\"m-personalizado\">servicio de guardia la recepción e incoación,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en su caso, <mark class=\"m-personalizado\">de los procesos</mark> correspondientes a los atestados, denuncias y querellas <mark class=\"m-personalizado\">que se presenten durante el tiempo de guardia,</mark> la realización de las <mark class=\"m-personalizado\">primeras diligencias de instrucción criminal</mark> que resulten procedentes, <mark class=\"m-personalizado\">entre</mark> ellas las <mark class=\"m-personalizado\">medidas cautelares de</mark> protección a la víctima, la adopción de las resoluciones oportunas</span></span> acerca de la <mark class=\"m-personalizado\">situación personal</mark> de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1312\">quienes sean conducidos como <mark class=\"m-personalizado\">detenidos a</mark> presencia judicial</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">la celebración de los <mark class=\"m-personalizado\">juicios inmediatos de faltas</mark> previstos en la Ley de Enjuiciamiento Criminal, <mark class=\"m-personalizado\">la tramitación de diligencias urgentes</mark> y de otras actuaciones que el Título III del Libro IV de la Ley de Enjuiciamiento Criminal atribuye al <mark class=\"m-autoridad\">Juez</mark> de guardia.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">Y, asimismo, la práctica de cualesquiera otras actuaciones de carácter urgente o inaplazable de entre las que la Ley atribuye a los Juzgados de Instrucción y a los Juzgados de Violencia sobre la Mujer.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1311\">🎯 1 pregunta</mark></p><p><b>2.</b> En cada circunscripción judicial, las <mark class=\"m-resp r-ia\" data-q=\"15-ia-1313\">normas generales de reparto</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">determinarán</mark> el <mark class=\"m-autoridad\">órgano</mark> judicial a que en definitiva <mark class=\"m-accion\">habrá</mark> de corresponder el conocimiento de los asuntos que ingresen a través del servicio de guardia y <mark class=\"m-accion\">podrán asignar</mark> al <mark class=\"m-autoridad\">Juzgado</mark> que en cada momento desempeñe tales cometidos el trámite y resolución de determinadas categorías de procedimientos de los que integran la competencia de los Juzgados de Instrucción.</span></span></p><p data-ex=\"*\"><b>3.</b> <mark class=\"m-personalizado\">Igualmente</mark> <mark class=\"m-accion\">constituirá</mark> <mark class=\"m-personalizado\">objeto del servicio de guardia</mark> la adopción <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-personalizado\">medidas cautelares respecto</mark> de las <mark class=\"m-autoridad\">personas</mark> comprendidas en el ámbito de aplicación de la Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal <mark class=\"m-personalizado\">de los</mark> <mark class=\"m-autoridad\">menores,</mark> <mark class=\"m-personalizado\">o</mark> la práctica de <mark class=\"m-personalizado\">diligencias restrictivas de los derechos fundamentales</mark> de dichas <mark class=\"m-autoridad\">personas,</mark> cuando su necesidad se suscite <mark class=\"m-personalizado\">fuera de las horas de</mark> <mark class=\"m-autoridad\">audiencia</mark></span></span> <mark class=\"m-personalizado\">del</mark> correspondiente <mark class=\"m-autoridad\">Juzgado de Menores,</mark> siempre que <mark class=\"m-resp\" data-q=\"15-312,15-ia-1314\">en la demarcación de dicho <mark class=\"m-autoridad\">Juzgado de Menores</mark> no exista un servicio de guardia propio de esta clase de <mark class=\"m-autoridad\">órganos</mark> jurisdiccionales</mark>. A estos efectos el <mark class=\"m-autoridad\">Juez</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">Instrucción que atienda el servicio de guardia <mark class=\"m-accion\">actuará</mark> en sustitución del correspondiente <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1315\">Juez de Menores</mark>.</mark> Adoptada la decisión que proceda, el <mark class=\"m-autoridad\">Juez</mark> de Instrucción en funciones de guardia <mark class=\"m-accion\">remitirá</mark> lo actuado al <mark class=\"m-autoridad\">órgano competente</mark> y <mark class=\"m-accion\">pondrá</mark> a su disposición, en su caso, al <mark class=\"m-autoridad\">menor</mark> de que se trate.</span></span></p><p><b>4.</b> <mark class=\"m-personalizado\">También</mark> <mark class=\"m-accion\">será</mark> objeto del <mark class=\"m-personalizado\">servicio de guardia la regularización de la situación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">personal de quienes sean <mark class=\"m-personalizado\">detenidos</mark> por su presunta participación en delitos cuya instrucción sea <mark class=\"m-personalizado\">competencia</mark> de los <mark class=\"m-autoridad\">Juzgados de Violencia</mark> sobre la Mujer <mark class=\"m-personalizado\">y la resolución</mark> de las <mark class=\"m-personalizado\">solicitudes</mark> de adopción de las <mark class=\"m-personalizado\">órdenes de protección</mark> de las víctimas de los mismos, siempre que dichas solicitudes se presenten y los detenidos sean puestos a disposición judicial <mark class=\"m-personalizado\">fuera de las</mark> horas de <mark class=\"m-autoridad\">audiencia</mark> de dichos Juzgados. <mark class=\"m-personalizado\">A estos efectos,</mark> el <mark class=\"m-autoridad\">Juez</mark> de Instrucción que atienda el servicio de guardia <mark class=\"m-accion\">actuará</mark> en <mark class=\"m-personalizado\">sustitución</mark> del correspondiente <mark class=\"m-autoridad\">Juez de Violencia</mark> sobre la Mujer. <mark class=\"m-personalizado\">Adoptada</mark> la decisión que proceda, el <mark class=\"m-autoridad\">Juez</mark> de Instrucción en funciones de guardia <mark class=\"m-accion\">remitirá</mark> <mark class=\"m-personalizado\">lo actuado al</mark> <mark class=\"m-autoridad\">órgano competente</mark> y <mark class=\"m-accion\">pondrá</mark> a su disposición, en su caso, al imputado.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1316\">🎯 1 pregunta</mark></p><p><b>5.</b> <mark class=\"m-autoridad\">El Juez</mark> que en cada circunscripción <span class=\"ex-plg\"><span class=\"ex-plg-t\">judicial desempeñe el <mark class=\"m-autoridad\">servicio de guardia</mark> <mark class=\"m-accion\">conocerá</mark> <mark class=\"m-personalizado\">también,</mark> en idéntico <mark class=\"m-personalizado\">cometido de sustitución,</mark> de aquellas <mark class=\"m-personalizado\">actuaciones urgentes</mark> que el artículo 70 de la Ley 1/2000, de 7 de enero, de <mark class=\"m-personalizado\">Enjuiciamiento Civil,</mark> atribuye a los <mark class=\"m-autoridad\">Jueces</mark> Decanos, así como las de igual naturaleza propias de la <mark class=\"m-autoridad\">oficina</mark> del <mark class=\"m-personalizado\">Registro Civil</mark> y las que asigna a los Juzgados de lo Contencioso-administrativo el segundo párrafo del apartado quinto del artículo 8 de la Ley 29/1998, de 13 de julio, siempre y cuando las mismas sean inaplazables y se susciten fuera de las horas de <mark class=\"m-autoridad\">audiencia del órgano</mark> a que estuvieren encomendados tales cometidos. Realizada que sea la intervención procedente, <mark class=\"m-accion\">se trasladará</mark> lo actuado al <mark class=\"m-autoridad\">órgano competente</mark> o a la <mark class=\"m-autoridad\">oficina</mark> de reparto, en su caso.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1318\">🎯 1 pregunta</mark></p><p><b>6.</b> En aquellos partidos judiciales en <span class=\"ex-plg\"><span class=\"ex-plg-t\">que exista separación entre Juzgados de Primera Instancia y Juzgados de Instrucción y el volumen de trabajo lo requiera, la <mark class=\"m-autoridad\">Sala de Gobierno</mark> correspondiente, oída la Junta de <mark class=\"m-autoridad\">Jueces,</mark> <mark class=\"m-accion\">podrá proponer</mark> al <mark class=\"m-autoridad\">Consejo</mark> General del Poder Judicial el establecimiento de un servicio especial para atender a las actuaciones de carácter inaplazable que dentro de la jurisdicción civil o en el ámbito del</span></span> Registro Civil, se susciten en <mark class=\"m-resp r-ia\" data-q=\"15-ia-1319\">días y horas inhábiles</mark>.</p><p><b>7.</b> Del mismo modo, las Juntas <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-autoridad\">Jueces</mark> <mark class=\"m-accion\">podrán encomendar</mark> al <mark class=\"m-autoridad\">Juzgado</mark> en funciones de guardia la atención de</span></span> aquellos servicios comunes de carácter <mark class=\"m-resp r-ia\" data-q=\"15-ia-1320\">gubernativo</mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\">exijan una prestación continuada.\"</span></span></p>"],["ARTÍCULO 47 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p>A los efectos de lo establecido <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los artículos 796, 799 bis y 962 de la Ley de Enjuiciamiento Criminal, <mark class=\"m-personalizado\">la asignación</mark> de espacios temporales para aquellas citaciones que la Policía Judicial realice ante los Juzgados de guardia y Juzgados de Violencia sobre la Mujer <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">realizará</mark> <mark class=\"m-personalizado\">a través de una</mark> <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1321\">Agenda Programada de Citaciones (APC)</mark>,</mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">detallará</mark> <mark class=\"m-personalizado\">franjas horarias disponibles</mark> en dichos Juzgados para esta finalidad.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">Tratándose <u class=\"m-clave\">de</u> <mark class=\"m-autoridad\">Juzgados de Violencia</mark> sobre <u class=\"m-clave\">la</u> Mujer <mark class=\"m-personalizado\">las franjas horarias</mark> que se reserven <mark class=\"m-accion\">comprenderán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">únicamente</u> los días laborables y las horas de</mark> <mark class=\"m-autoridad\">audiencia;</mark> las <mark class=\"m-destacable\">citaciones se</mark> <mark class=\"m-accion\">señalarán</mark> <mark class=\"m-personalizado\">para el día hábil más próximo, y si éste no</mark> tuviere <mark class=\"m-personalizado\">horas disponibles,</mark> el señalamiento <mark class=\"m-accion\">se hará</mark> para <mark class=\"m-personalizado\">el <u class=\"m-clave\">siguiente</u> día hábil más próximo.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1322,15-ia-1323\">🎯 2 preguntas</mark></p><p style=\"margin-left:36px\"><b>I.</b> <mark class=\"m-personalizado\">Si hubiera más de un servicio de guardia o más de un</mark> <mark class=\"m-autoridad\">Juzgado</mark> <mark class=\"m-personalizado\">de Violencia</mark> sobre la <span class=\"ex-plg\"><span class=\"ex-plg-t\">Mujer en la circunscripción para instrucción de Diligencias Urgentes, las citaciones <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">realizarán</mark> al servicio de guardia o <mark class=\"m-autoridad\">Juzgado</mark> de Violencia sobre la Mujer que corresponda <mark class=\"m-personalizado\">con arreglo a las normas de reparto existentes,</mark> así como a los acuerdos adoptados en el seno <mark class=\"m-personalizado\">de</mark> la <mark class=\"m-autoridad\">Comisión</mark> Provincial de Coordinación de la Policía Judicial.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1324\">🎯 1 pregunta</mark></p><p style=\"margin-left:36px\"><b>II.</b> <mark class=\"m-accion\">Tendrán</mark> <mark class=\"m-personalizado\">preferencia</mark> en la asignación <span class=\"ex-plg\"><span class=\"ex-plg-t\">de espacios horarios preestablecidos <mark class=\"m-personalizado\">los testigos</mark> <mark class=\"m-autoridad\">extranjeros</mark> <mark class=\"m-personalizado\">y nacionales desplazados</mark> temporalmente fuera de su localidad, a <mark class=\"m-personalizado\">los efectos</mark> de facilitar la <mark class=\"m-personalizado\">práctica de</mark> <mark class=\"m-destacable\">prueba preconstituida,</mark> de acuerdo con lo dispuesto en el apartado 2 del artículo 797 de la Ley de Enjuiciamiento Criminal.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1325\">🎯 1 pregunta</mark></p><p>A los efectos previstos en el <span class=\"ex-plg\"><span class=\"ex-plg-t\">artículo 800.3 de la Ley de Enjuiciamiento Criminal, los Juzgados de Instrucción en servicio de guardia ordinaria y los Juzgados de Violencia sobre la Mujer <mark class=\"m-accion\">realizarán</mark> directamente los señalamientos para la celebración <mark class=\"m-personalizado\">del juicio oral</mark> en las causas seguidas como procedimiento de enjuiciamiento rápido, siempre que no</span></span> hayan de dictar sentencia de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1326\">conformidad</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">acuerdo a lo previsto en el artículo 801 de la Ley de Enjuiciamiento Criminal.</span></span></p><p><mark class=\"m-autoridad\">El Juzgado de Instrucción</mark> en servicio <mark class=\"m-autoridad\">de guardia</mark> que, de <span class=\"ex-plg\"><span class=\"ex-plg-t\">conformidad con lo dispuesto en el artículo 54.2 de la Ley Orgánica 1/2004, de Medidas de Protección Integral contra la Violencia de Género, <mark class=\"m-personalizado\">haya de resolver sobre la situación personal del detenido por hechos</mark> cuyo conocimiento corresponda al <mark class=\"m-autoridad\">Juzgado de Violencia</mark> sobre la Mujer, <mark class=\"m-accion\">citará</mark> <mark class=\"m-personalizado\">a éste</mark> para comparecencia <mark class=\"m-personalizado\">ante dicho</mark> <mark class=\"m-autoridad\">Juzgado</mark> <mark class=\"m-personalizado\">en la misma fecha</mark> para la que hayan sido <mark class=\"m-personalizado\">citados por la</mark> <mark class=\"m-autoridad\">Policía Judicial la persona</mark> <mark class=\"m-personalizado\">denunciante y los testigos, en caso</mark> de que se decrete su <mark class=\"m-personalizado\">libertad.</mark> En el supuesto de que el detenido sea constituido en prisión, junto con el mandamiento</span></span> correspondiente, <mark class=\"m-accion\">se librará</mark> la orden de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1328\">traslado al <mark class=\"m-autoridad\">Juzgado</mark> de Violencia sobre la Mujer en la fecha indicada</mark>.</p><p data-ex=\"EX\"><mark class=\"m-personalizado\">Las asignaciones de fecha</mark> y hora para celebración de <span class=\"ex-plg\"><span class=\"ex-plg-t\">los <mark class=\"m-personalizado\">juicios orales</mark> en las causas seguidas <mark class=\"m-personalizado\">como</mark> procedimiento de <mark class=\"m-personalizado\">enjuiciamiento rápido</mark> <mark class=\"m-accion\">se realizarán</mark> <mark class=\"m-personalizado\">con arreglo</mark> a una <mark class=\"m-destacable\">Agenda Programada de <u class=\"m-clave\">Señalamientos.</u></mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1329,15-ia-2323\">🎯 2 preguntas</mark></p><p data-ex=\"*\">A este fin, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">establecerá</mark> <mark class=\"m-personalizado\">un turno de señalamientos entre los</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Juzgados de lo Penal</mark> <mark class=\"m-personalizado\">con la periodicidad que la Junta de</mark> <mark class=\"m-autoridad\">Jueces</mark> <mark class=\"m-personalizado\">determine,</mark> <mark class=\"m-autoridad\">el cual</mark> <mark class=\"m-accion\">deberá ser aprobado</mark> por la <mark class=\"m-autoridad\">Sala de Gobierno del Tribunal Superior de Justicia</mark> y <mark class=\"m-personalizado\"><u class=\"m-clave\">comunicado</u> al</mark> <mark class=\"m-autoridad\">Consejo General del</mark> Poder <mark class=\"m-autoridad\">Judicial.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"15-313,15-ia-1330\">🎯 2 preguntas</mark></p><p style=\"margin-left:36px\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">– a.- <mark class=\"m-personalizado\">En aquellas demarcaciones con más de cinco</mark> <mark class=\"m-autoridad\">Juzgados de lo Penal,</mark> <mark class=\"m-accion\">se establecerá</mark> un <mark class=\"m-personalizado\"><u class=\"m-clave\">turno</u> diario de lunes a viernes</mark> en el que <mark class=\"m-personalizado\">uno o dos Juzgados</mark> de lo Penal <mark class=\"m-accion\">reservarán</mark> <mark class=\"m-personalizado\">íntegramente su Agenda</mark> para que los <mark class=\"m-autoridad\">Juzgados de guardia</mark> de la demarcación territorial <mark class=\"m-personalizado\">realicen directamente el señalamiento de los juicios orales</mark> en estas causas.</span></span> De acuerdo con el artículo 800.3 de la Ley de Enjuiciamiento Criminal, el señalamiento por los Juzgados de guardia <mark class=\"m-accion\">deberá realizarse</mark> <mark class=\"m-personalizado\">en la fecha más próxima</mark> posible <mark class=\"m-personalizado\">a partir del vencimiento del plazo de presentación del escrito de defensa,</mark> si éste no se hubiere presentado en el acto o de forma oral. <mark class=\"m-personalizado\">El máximo número de señalamientos</mark> por estos procedimientos <mark class=\"m-accion\">será</mark> de <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1331\">quince</mark>,</mark> y consecuentemente, en el momento en que <mark class=\"m-personalizado\">se cubra</mark> este cupo el señalamiento <mark class=\"m-accion\">deberá realizarse</mark> <mark class=\"m-personalizado\">para el siguiente día de</mark> turno disponible. <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1332\">🎯 1 pregunta</mark></p><p style=\"margin-left:36px\">– b.- En aquellas demarcaciones con <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">más</mark> <mark class=\"m-personalizado\">de un</mark> <mark class=\"m-autoridad\">Juzgado de lo Penal</mark> <mark class=\"m-personalizado\">y menos de seis</mark> <mark class=\"m-accion\">se establecerá</mark> un <mark class=\"m-personalizado\">turno semanal</mark> de señalamientos en el que uno de los Juzgados de lo Penal <mark class=\"m-accion\">reservarán</mark> su <mark class=\"m-personalizado\">Agenda de lunes a viernes</mark> para que los <mark class=\"m-autoridad\">Juzgados de guardia</mark> de la demarcación territorial <mark class=\"m-personalizado\">realicen</mark> directamente el <mark class=\"m-personalizado\">señalamiento de los juicios orales del nuevo</mark> procedimiento de enjuiciamiento urgente. Dentro de este turno semanal, los señalamientos <mark class=\"m-accion\">se realizarán</mark> para el primer día hábil de la semana, hasta un límite de quince señalamientos, procediéndose entonces al señalamiento para el siguiente día hábil de la semana, y así sucesivamente.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1333\">🎯 1 pregunta</mark></p><p style=\"margin-left:36px\">– c.- En aquellas demarcaciones con <span class=\"ex-plg\"><span class=\"ex-plg-t\">un único <mark class=\"m-autoridad\">Juzgado</mark> de lo Penal,</span></span> éste <mark class=\"m-accion\">reservará</mark> en su Agenda <mark class=\"m-resp r-ia\" data-q=\"15-ia-1334\">uno o dos días a la semana</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">entre el lunes y el viernes, para que los Juzgados de guardia realicen directamente el señalamiento de los juicios orales del nuevo procedimiento de enjuiciamiento urgente.</span></span></p><p>En aquellos partidos judiciales con <mark class=\"m-personalizado\">más de</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">un Juzgado de Instrucción, las Salas de Gobierno de los Tribunales Superiores de Justicia,</mark> <mark class=\"m-personalizado\">a propuesta de las</mark> <mark class=\"m-autoridad\">Juntas de Jueces,</mark> <mark class=\"m-accion\">adaptarán</mark> <mark class=\"m-personalizado\">las normas</mark> de <mark class=\"m-personalizado\">reparto</mark> de estos Juzgados con la finalidad de atribuir al <mark class=\"m-autoridad\">Juzgado</mark> de guardia la competencia para el conocimiento de todas las faltas cuyo atestado o</span></span> denuncia haya ingresado durante el <mark class=\"m-resp r-ia\" data-q=\"15-ia-1335\">servicio de guardia ordinaria</mark>.</p><p>A los efectos de asegurar la <span class=\"ex-plg\"><span class=\"ex-plg-t\">efectividad de lo dispuesto en el Capítulo siguiente <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">establecerán</mark> <mark class=\"m-personalizado\">protocolos</mark> de colaboración en el ámbito provincial <mark class=\"m-personalizado\">en el seno de las</mark> <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1336\">Comisiones Provinciales de Policía Judicial</mark>.</mark> <mark class=\"m-personalizado\">Asimismo, en</mark> el ámbito de <mark class=\"m-personalizado\">los respectivos partidos</mark> judiciales, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">establecer protocolos de colaboración específicos</mark> entre Policía Judicial, <mark class=\"m-autoridad\">Fiscalía</mark> y las respectivas Juntas de <mark class=\"m-autoridad\">Jueces,</mark> representadas por el <mark class=\"m-autoridad\">Juez</mark> Decano, posibilitando la incorporación a estos ámbitos de colaboración de los Colegios Profesionales de <mark class=\"m-autoridad\">Abogados</mark> y Procuradores, <mark class=\"m-autoridad\">Ministerio</mark> de Justicia y Comunidades Autónomas.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">Por último <mark class=\"m-accion\">podrán establecerse</mark> protocolos en el ámbito de una Comunidad Autónoma, pudiéndose constituir <mark class=\"m-autoridad\">Órganos</mark> que conformen igual representación.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1337\">🎯 1 pregunta</mark></p><p>Las Comisiones Provinciales de Policía Judicial <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">serán</mark> oídas previamente al establecimiento de los criterios de señalamiento de vistas por la correspondiente <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1338\">Sala de Gobierno</mark>,</mark> e <mark class=\"m-accion\">informarán</mark> a ésta</span></span></p><p><mark class=\"m-personalizado\">En el ámbito de cada Comunidad Autónoma se</mark> <mark class=\"m-accion\">constituirá</mark> una <mark class=\"m-autoridad\">Comisión</mark> Mixta <mark class=\"m-personalizado\">para el seguimiento de los Juicios Rápidos, integrada por el</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Presidente del Tribunal</mark> <mark class=\"m-personalizado\">Superior de Justicia, en representación de la</mark> <mark class=\"m-autoridad\">Sala de Gobierno,</mark> <mark class=\"m-personalizado\">por un representante del</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-personalizado\">de Justicia y de la Comunidad</mark> <mark class=\"m-autoridad\">Autónoma,</mark> <mark class=\"m-personalizado\">un representante</mark> de la <mark class=\"m-autoridad\">Fiscalía,</mark> un representante de los Colegios de <mark class=\"m-autoridad\">Abogados</mark> y un representante de los Colegios de Procuradores.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1339\">🎯 1 pregunta</mark></p><p>Esta <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-accion\">recabará</mark> y <mark class=\"m-accion\">analizará</mark> <mark class=\"m-personalizado\">los datos</mark> que le proporcionen los <mark class=\"m-autoridad\">órganos</mark> judiciales <mark class=\"m-personalizado\">sobre el número de procedimientos</mark> tramitados y celebrados <mark class=\"m-personalizado\">como juicios rápidos, plazos</mark> de celebración, número de <mark class=\"m-personalizado\">suspensiones y sus causas, <u class=\"m-clave\">e</u></mark> <mark class=\"m-accion\">informará</mark> <mark class=\"m-personalizado\">periódicamente al</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"15-ia-1340\">Consejo General del Poder Judicial</mark></mark> a los efectos de lo previsto en el artículo 46.1.</p><p><mark class=\"m-autoridad\">Las Salas de Gobierno y las Juntas de Jueces</mark> en el ejercicio de sus <span class=\"ex-plg\"><span class=\"ex-plg-t\">normales atribuciones gubernativas y con sujeción a los términos del presente Reglamento, <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">aprobar las normas complementarias</mark> que en materia de <mark class=\"m-personalizado\">distribución de asuntos, régimen interno, cuadro de <mark class=\"m-resp r-ia\" data-q=\"15-ia-1341\">sustituciones</mark> u otras cuestiones</mark> de su competencia, estimen procedentes.</span></span></p></div></div><div class=\"ex-linea\">ARTÍCULO 2: <mark class=\"m-resp ex-q r-ia\" data-q=\"15-ia-1216,15-ia-1342,15-ia-1343\">🎯 3 preguntas más de este artículo</mark>"]];
